-- stochastic-processes implementation for PoissonProcess
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))

local Module = {}
function Module.ArrivalTimes(rate,count,uniforms)
    Num.Positive(rate,"event rate"); assert(#uniforms>=count,"not enough uniform variates")
    local times=table.create(count); local time=0
    for i=1,count do assert(uniforms[i]>0 and uniforms[i]<1,"uniform variates must lie in (0,1)"); time+=-math.log(uniforms[i])/rate; times[i]=time end
    return times
end

return Module
